from itertools import product

def partitions(n, cap=None):
    if n == 0:
        yield ()
        return
    if cap is None or cap > n:
        cap = n
    for a in range(cap, 0, -1):
        for tail in partitions(n-a, a):
            yield (a,) + tail

def contains(a, b):
    # a contained in b
    return all((a[k] if k < len(a) else 0) <= (b[k] if k < len(b) else 0)
               for k in range(max(len(a), len(b))))

def horizontal_strip(a, b):
    if not contains(a, b):
        return False
    width = max(a[0] if a else 0, b[0] if b else 0)
    return all(sum(x >= col for x in b) - sum(x >= col for x in a) in (0, 1)
               for col in range(1, width + 1))

def pieri(a, k, q, r):
    return {b for b in partitions(sum(a) + k)
            if len(b) <= r and b[0] <= q and horizontal_strip(a, b)}

def slots(i, j, p, c):
    return {
        'x0': (i,) * j,
        'x1': (i+1,) + (i,) * (j-1),
        'y1': (i,) * j + (1,),
        'gamma': (i+2,) + (i,) * (j-1) if p >= 2 else None,
        'x2': (i+1, i+1) + (i,) * (j-2),
        'z': (i+1,) + (i,) * (j-1) + (1,),
        'y2': (i,) * j + (2,),
        'theta': (i,) * j + (1, 1) if c >= 2 else None,
    }

def nonnull(*xs):
    return {x for x in xs if x is not None}

tuple_count = identity_count = boundary_count = 0
for i, j in product(range(2, 7), repeat=2):
    for p, c in product(range(1, 6), repeat=2):
        if min(p, c) != 1:
            continue
        q, r, S = i+p, j+c, slots(i, j, p, c)
        checks = (
            (pieri(S['x0'], 1, q, r), nonnull(S['x1'], S['y1'])),
            (pieri(S['x0'], 2, q, r), nonnull(S['gamma'], S['z'], S['y2'])),
            (pieri(S['x1'], 1, q, r), nonnull(S['gamma'], S['x2'], S['z'])),
            (pieri(S['y1'], 1, q, r), nonnull(S['z'], S['y2'], S['theta'])),
        )
        for actual, expected in checks:
            assert actual == expected, (i, j, p, c, actual, expected)
            identity_count += 1
        if p == c == 1:
            columns = ('x2', 'z', 'y2')
            rows = [[int(S[name] in pieri(lam, k, q, r)) for name in columns]
                    for lam, k in ((S['x0'], 2), (S['x1'], 1), (S['y1'], 1))]
            assert rows == [[0, 1, 1], [1, 1, 0], [0, 1, 1]], rows
            minor = [[rows[a][b] for b in (1, 2)] for a in (0, 1)]
            det = minor[0][0]*minor[1][1] - minor[0][1]*minor[1][0]
            assert minor == [[1, 1], [1, 0]] and det == -1, (minor, det)
            boundary_count += 1
        tuple_count += 1
print('INPUT_I_J: 2..6')
print('INPUT_P_C: 1..5 with min(p,c)=1')
print('PARAMETER_TUPLES:', tuple_count)
print('PIERI_IDENTITIES_CHECKED:', identity_count)
print('DOUBLY_BOUNDARY_MATRIX_CHECKS:', boundary_count)
print('DOUBLY_BOUNDARY_MATRIX_COLUMNS: [x2,z,y2]')
print('DOUBLY_BOUNDARY_MATRIX: [[0,1,1],[1,1,0],[0,1,1]]')
print('DOUBLY_BOUNDARY_MINOR_ROWS_ONE_BASED: [1,2]')
print('DOUBLY_BOUNDARY_MINOR_COLUMNS: [z,y2]')
print('DOUBLY_BOUNDARY_MINOR: [[1,1],[1,0]]')
print('DOUBLY_BOUNDARY_MINOR_DETERMINANT: -1')
